sctrls.example:
assertInput{
    flag: U;
    flag2: D;
    flag3: L;
    flag4: R;
}

camera{
    view: "Free";
    pos.x: 0;
    pos.y: 0;
}

lifebarAction{
    top: 1;
    time: 60;
    timemul: 1.0;
    text: "Ready";
    font.no: 0;
    font.bank: 0;
    font.align: 0;
    font.color: 256, 256, 256, 256;
    refreshtype: 2;
}

mapReset{
    exclude: "level_";
    exclude2: "experience_";
    exclude3: "score_";
}

mapSet{map: "example"; value: 1}

# Reset first 10 indexes (nightly build only)
for i = 0; 9; 1:
    mapSet{map: "indexed_map"; index: $i; value: 0}
}

modifyBgm{
    volume: 80;
    loopstart: 0;
    loopend: 100000;
    position: 0;
    freqmul: 1.0;
    loopcount: 0;
}

modifyReflection{
    anim: 0;
    animelem: 1;
    animplayerno: 0;
    spriteplayerno: 0;
    color: 128, 160, 255;
    intensity: 128;
    offset: 0, 0;
    window: -100, -100, 100, 100;
    xshear: 0.1;
    xscale: 1.0;
    yscale: 1.0;
    focallength: 1.0;
}

modifyShadow{
    anim: 0;
    animelem: 1;
    animplayerno: 0;
    spriteplayerno: 0;
    color: 128, 128, 128;
    intensity: 128;
    offset: 0, 0;
    window: -100, -100, 100, 100;
    xshear: 0.1;
    xscale: 1.0;
    yscale: 1.0;
    focallength: 1.0;
}

modifyStageVar{
    camera.verticalfollow: 0.2;
    camera.tension: 50;
    stageinfo.autoturn: true;
    stageinfo.xscale: 1.0;
    stageinfo.yscale: 1.0;
    shadow.offset: 0, 0;
    reflection.offset: 0, 0;
}

parentMapAdd{
    map: "example";
    value: 1;
}

parentMapSet{
    map: "example";
    value: 1;
}

playBgm{
    source: "match";
}

if ctrl && prevMoveType = H {
	runState{value: -1}
}

shaderSet{
    shader: "myShader";
    time: -1;
    shaderparam.p0: 1.0;
    shaderparam.p1: 0.5;
    shadertex1.spr: 0, 0;
    shadertex2.anim: 0;
}

# Invert all directions
shiftInput{input: U; output: D}
shiftInput{input: D; output: U}
shiftInput{input: L; output: R}
shiftInput{input: R; output: L}

# Disable button a
shiftInput{input: a; output: none}

text{
    text: "Value %d";
    params: 42;
    removetime: 60;
    layerno: 1;
    localcoord: 320, 240;
    font: 0;
    bank: 0;
    align: 1;
    angle: 0;
    pos: 10, 20;
    scale: 1.0, 1.0;
    color: 256, 256, 256, 256;
    id: 1;
    textspacing: 0, 0;
    textdelay: 0;
    velocity: 0, 0;
    accel: 0, 0;
    friction: 0.95, 0.95;
    xshear: 0;
    maxdist: 0;
    hidewithbars: true;
}

transformClsn{
    group: clsn1;
    scale: 1.1, 1.1;
    angle: 15;
    pivot: 0, -50;
}

transformSprite{
    window: -100, -100, 100, 100;
    xshear: 0.1;
    projection: "perspective";
    focallength: 1.0;
}
